#include <bits/stdc++.h>
using namespace std;

int mod_pow(int base, int exp, int mod) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return result;
}

const int MAX = 300005;
unsigned long long dp_arr[27][MAX];
int fact[MAX], inv_fact[MAX];

int perm(int n, int m, int mod) {
    return (long long)fact[n] * inv_fact[n - m] % mod;
}

int main() {
    int n, K, MOD;
    scanf("%d %d %d", &n, &K, &MOD);
    if (n % 2 != 0) {
        printf("%d\n", mod_pow(K, n, MOD));
        return 0;
    }
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = (long long)fact[i - 1] * i % MOD;
    }
    inv_fact[n] = mod_pow(fact[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; --i) {
        inv_fact[i] = (long long)inv_fact[i + 1] * (i + 1) % MOD;
    }
    dp_arr[0][0] = 1ULL;
    for (int k = 0; k < K; ++k) {
        for (int i = 1; i <= n; ++i) {
            if ((i & n) != i) continue;
            int block_mask = 1 << (31 - __builtin_clz(i));
            unsigned long long &res = dp_arr[k + 1][i];
            res = 0ULL;
            for (int j = i - block_mask; j >= 0; j = (j - 1) & i) {
                int j_plus = j + block_mask;
                res += dp_arr[k][i ^ j_plus] * inv_fact[j_plus];
                if (++cnt == 17) {
                    res %= MOD;
                    cnt = 0;
                }
                if (j == 0) break;
            }
            res %= MOD;
        }
    }
    int answer = 0;
    for (int i = 0; i <= K; ++i) {
        answer = (answer + (long long)fact[n] * dp_arr[i][n] % MOD * perm(K, i, MOD)) % MOD;
    }
    printf("%d\n", (mod_pow(K, n, MOD) + MOD - answer) % MOD);
}
